struct timespec wait = {0, 0}, rem;
for (int attempt = 1; ; attempt++) {
    int rc = call_dependency(&out);
    if (rc == 0 || !transient_errno(rc) || attempt >= max_attempts) return rc;
    long ms = backoff_ms(attempt, 500, 2, 30000);      /* base, multiplier, cap */
    ms = (long)((double)ms * ((double)rand_r(&seed) / RAND_MAX));  /* full jitter */
    wait.tv_sec = ms / 1000; wait.tv_nsec = (ms % 1000) * 1000000L;
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &wait, &rem) == EINTR) wait = rem;
}
